-- Skylight Reflections Marketing sales, services and invoicing suite.
-- Professional-service invoices remain separate from Local Pros Lead Buyer billing.

create table if not exists public.skylight_service_catalog (
  id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade,
  name text not null, slug text not null, category text, short_description text, description text,
  pricing_model text not null default 'custom_quote' check (pricing_model in ('fixed','starting_at','hourly','monthly','custom_quote')),
  default_price_cents integer check (default_price_cents is null or default_price_cents>=0), unit_label text, billing_label text,
  public_visible boolean not null default true, active boolean not null default true, featured boolean not null default false,
  sort_order integer not null default 100, cta_label text not null default 'Request a Quote', created_by uuid references auth.users(id),
  updated_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique(tenant_id,slug)
);
create table if not exists public.skylight_signal_service_map (
  id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade,
  signal_key text not null, service_slug text not null, weight integer not null default 10 check(weight between 0 and 100),
  active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique(tenant_id,signal_key,service_slug)
);
create table if not exists public.skylight_clients (
  id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade,
  business_id uuid references public.businesses(id) on delete set null, prospect_id uuid references public.business_prospects(id) on delete set null,
  company_name text not null, contact_name text, email text, phone text, billing_address1 text, billing_address2 text, city text, state text,
  postal_code text, country text not null default 'US', tax_id text, status text not null default 'active' check(status in('prospect','active','inactive')),
  internal_notes text, created_by uuid references auth.users(id), updated_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create unique index if not exists skylight_clients_tenant_prospect_uidx on public.skylight_clients(tenant_id,prospect_id) where prospect_id is not null;
create index if not exists skylight_clients_tenant_company_idx on public.skylight_clients(tenant_id,company_name);
create table if not exists public.skylight_invoice_counters (
  tenant_id uuid not null references public.tenants(id) on delete cascade, invoice_year integer not null, last_number integer not null default 0, primary key(tenant_id,invoice_year)
);
create table if not exists public.skylight_invoices (
  id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade,
  client_id uuid not null references public.skylight_clients(id) on delete restrict, invoice_number text,
  status text not null default 'draft' check(status in('draft','sent','viewed','partial','paid','overdue','void')), currency text not null default 'usd',
  issue_date date not null default current_date, due_date date, subtotal_cents integer not null default 0 check(subtotal_cents>=0),
  discount_cents integer not null default 0 check(discount_cents>=0), tax_rate_bps integer not null default 0 check(tax_rate_bps between 0 and 10000),
  tax_cents integer not null default 0 check(tax_cents>=0), total_cents integer not null default 0 check(total_cents>=0), amount_paid_cents integer not null default 0,
  balance_due_cents integer not null default 0, deposit_required_cents integer not null default 0 check(deposit_required_cents>=0), terms text, client_note text, internal_note text,
  public_token uuid not null default gen_random_uuid(), sent_at timestamptz, viewed_at timestamptz, paid_at timestamptz, voided_at timestamptz,
  stripe_customer_id text, stripe_invoice_id text, hosted_invoice_url text, invoice_pdf_url text, created_by uuid references auth.users(id), updated_by uuid references auth.users(id),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(tenant_id,invoice_number), unique(public_token)
);
create index if not exists skylight_invoices_tenant_status_idx on public.skylight_invoices(tenant_id,status,due_date);
create index if not exists skylight_invoices_client_idx on public.skylight_invoices(client_id,created_at desc);
create table if not exists public.skylight_invoice_items (
  id uuid primary key default gen_random_uuid(), invoice_id uuid not null references public.skylight_invoices(id) on delete cascade,
  service_id uuid references public.skylight_service_catalog(id) on delete set null, description text not null, detail text,
  quantity numeric(10,2) not null default 1 check(quantity>0), unit_price_cents integer not null default 0 check(unit_price_cents>=0),
  line_discount_cents integer not null default 0 check(line_discount_cents>=0), line_total_cents integer not null default 0 check(line_total_cents>=0),
  sort_order integer not null default 100, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create index if not exists skylight_invoice_items_invoice_idx on public.skylight_invoice_items(invoice_id,sort_order);
create table if not exists public.skylight_invoice_payments (
  id uuid primary key default gen_random_uuid(), invoice_id uuid not null references public.skylight_invoices(id) on delete cascade,
  kind text not null default 'payment' check(kind in('payment','refund')), amount_cents integer not null check(amount_cents>0), paid_at timestamptz not null default now(),
  method text not null default 'other', reference text, notes text, recorded_by uuid references auth.users(id), created_at timestamptz not null default now()
);
create index if not exists skylight_invoice_payments_invoice_idx on public.skylight_invoice_payments(invoice_id,paid_at desc);
create table if not exists public.skylight_sales_opportunities (
  id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade,
  prospect_id uuid references public.business_prospects(id) on delete cascade, business_id uuid references public.businesses(id) on delete set null,
  growth_opportunity_id uuid references public.growth_opportunities(id) on delete set null, primary_service_slug text,
  recommended_service_slugs text[] not null default '{}', evidence_flags text[] not null default '{}', score integer not null default 0 check(score between 0 and 100),
  priority text not null default 'medium' check(priority in('low','medium','high','hot')), stage text not null default 'new' check(stage in('new','research','contact_ready','contacted','qualified','proposal','won','lost','nurture')),
  estimated_value_cents integer check(estimated_value_cents is null or estimated_value_cents>=0), assigned_user_id uuid references auth.users(id), last_contact_at timestamptz,
  next_follow_up_at timestamptz, client_id uuid references public.skylight_clients(id) on delete set null, invoice_id uuid references public.skylight_invoices(id) on delete set null,
  notes text, lost_reason text, active boolean not null default true, won_at timestamptz, lost_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique(tenant_id,prospect_id)
);
create index if not exists skylight_sales_opportunities_queue_idx on public.skylight_sales_opportunities(tenant_id,active,stage,priority,score desc);
create index if not exists skylight_sales_opportunities_business_idx on public.skylight_sales_opportunities(business_id);
create table if not exists public.skylight_sales_campaigns (
  id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade, name text not null, slug text not null,
  campaign_type text not null default 'service_outreach' check(campaign_type in('service_outreach','lead_buyer_recruitment','custom')), service_slug text, description text,
  status text not null default 'active' check(status in('draft','active','paused','completed')), filters jsonb not null default '{}'::jsonb,
  created_by uuid references auth.users(id), updated_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(tenant_id,slug)
);
create table if not exists public.skylight_sales_campaign_members (
  id uuid primary key default gen_random_uuid(), campaign_id uuid not null references public.skylight_sales_campaigns(id) on delete cascade,
  opportunity_id uuid references public.skylight_sales_opportunities(id) on delete cascade, growth_opportunity_id uuid references public.growth_opportunities(id) on delete cascade,
  prospect_id uuid references public.business_prospects(id) on delete set null, business_id uuid references public.businesses(id) on delete set null,
  status text not null default 'queued' check(status in('queued','research','ready','contacted','replied','qualified','won','lost','skipped')),
  priority text not null default 'medium' check(priority in('low','medium','high','hot')), assigned_user_id uuid references auth.users(id), last_action_at timestamptz,
  next_action_at timestamptz, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create unique index if not exists skylight_campaign_member_opportunity_uidx on public.skylight_sales_campaign_members(campaign_id,opportunity_id) where opportunity_id is not null;
create unique index if not exists skylight_campaign_member_growth_uidx on public.skylight_sales_campaign_members(campaign_id,growth_opportunity_id) where growth_opportunity_id is not null;
create index if not exists skylight_campaign_members_queue_idx on public.skylight_sales_campaign_members(campaign_id,status,priority,next_action_at);

alter table public.skylight_service_catalog enable row level security; alter table public.skylight_signal_service_map enable row level security;
alter table public.skylight_clients enable row level security; alter table public.skylight_invoice_counters enable row level security; alter table public.skylight_invoices enable row level security;
alter table public.skylight_invoice_items enable row level security; alter table public.skylight_invoice_payments enable row level security; alter table public.skylight_sales_opportunities enable row level security;
alter table public.skylight_sales_campaigns enable row level security; alter table public.skylight_sales_campaign_members enable row level security;
drop policy if exists "public read active skylight services" on public.skylight_service_catalog;
create policy "public read active skylight services" on public.skylight_service_catalog for select to anon,authenticated using(active and public_visible);
drop policy if exists "staff manage skylight services" on public.skylight_service_catalog;
create policy "staff manage skylight services" on public.skylight_service_catalog for all to authenticated using(private.has_tenant_role(tenant_id,array['staff','admin','super_admin'])) with check(private.has_tenant_role(tenant_id,array['staff','admin','super_admin']));
drop policy if exists "staff manage skylight signal map" on public.skylight_signal_service_map;
create policy "staff manage skylight signal map" on public.skylight_signal_service_map for all to authenticated using(private.has_tenant_role(tenant_id,array['staff','admin','super_admin'])) with check(private.has_tenant_role(tenant_id,array['staff','admin','super_admin']));
drop policy if exists "staff manage skylight clients" on public.skylight_clients;
create policy "staff manage skylight clients" on public.skylight_clients for all to authenticated using(private.has_tenant_role(tenant_id,array['staff','admin','super_admin'])) with check(private.has_tenant_role(tenant_id,array['staff','admin','super_admin']));
drop policy if exists "staff manage skylight counters" on public.skylight_invoice_counters;
create policy "staff manage skylight counters" on public.skylight_invoice_counters for all to authenticated using(private.has_tenant_role(tenant_id,array['staff','admin','super_admin'])) with check(private.has_tenant_role(tenant_id,array['staff','admin','super_admin']));
drop policy if exists "staff manage skylight invoices" on public.skylight_invoices;
create policy "staff manage skylight invoices" on public.skylight_invoices for all to authenticated using(private.has_tenant_role(tenant_id,array['staff','admin','super_admin'])) with check(private.has_tenant_role(tenant_id,array['staff','admin','super_admin']));
drop policy if exists "staff manage skylight invoice items" on public.skylight_invoice_items;
create policy "staff manage skylight invoice items" on public.skylight_invoice_items for all to authenticated using(exists(select 1 from public.skylight_invoices i where i.id=invoice_id and private.has_tenant_role(i.tenant_id,array['staff','admin','super_admin']))) with check(exists(select 1 from public.skylight_invoices i where i.id=invoice_id and private.has_tenant_role(i.tenant_id,array['staff','admin','super_admin'])));
drop policy if exists "staff manage skylight invoice payments" on public.skylight_invoice_payments;
create policy "staff manage skylight invoice payments" on public.skylight_invoice_payments for all to authenticated using(exists(select 1 from public.skylight_invoices i where i.id=invoice_id and private.has_tenant_role(i.tenant_id,array['staff','admin','super_admin']))) with check(exists(select 1 from public.skylight_invoices i where i.id=invoice_id and private.has_tenant_role(i.tenant_id,array['staff','admin','super_admin'])));
drop policy if exists "staff manage skylight opportunities" on public.skylight_sales_opportunities;
create policy "staff manage skylight opportunities" on public.skylight_sales_opportunities for all to authenticated using(private.has_tenant_role(tenant_id,array['staff','admin','super_admin'])) with check(private.has_tenant_role(tenant_id,array['staff','admin','super_admin']));
drop policy if exists "staff manage skylight campaigns" on public.skylight_sales_campaigns;
create policy "staff manage skylight campaigns" on public.skylight_sales_campaigns for all to authenticated using(private.has_tenant_role(tenant_id,array['staff','admin','super_admin'])) with check(private.has_tenant_role(tenant_id,array['staff','admin','super_admin']));
drop policy if exists "staff manage skylight campaign members" on public.skylight_sales_campaign_members;
create policy "staff manage skylight campaign members" on public.skylight_sales_campaign_members for all to authenticated using(exists(select 1 from public.skylight_sales_campaigns c where c.id=campaign_id and private.has_tenant_role(c.tenant_id,array['staff','admin','super_admin']))) with check(exists(select 1 from public.skylight_sales_campaigns c where c.id=campaign_id and private.has_tenant_role(c.tenant_id,array['staff','admin','super_admin'])));
grant select on public.skylight_service_catalog to anon,authenticated; grant insert,update,delete on public.skylight_service_catalog to authenticated;
grant select,insert,update,delete on public.skylight_signal_service_map,public.skylight_clients,public.skylight_invoice_counters,public.skylight_invoices,public.skylight_invoice_items,public.skylight_invoice_payments,public.skylight_sales_opportunities,public.skylight_sales_campaigns,public.skylight_sales_campaign_members to authenticated;
revoke all on public.skylight_signal_service_map,public.skylight_clients,public.skylight_invoice_counters,public.skylight_invoices,public.skylight_invoice_items,public.skylight_invoice_payments,public.skylight_sales_opportunities,public.skylight_sales_campaigns,public.skylight_sales_campaign_members from anon;

create or replace function private.next_skylight_invoice_number(p_tenant uuid,p_date date) returns text language plpgsql security definer set search_path='' as $$
declare y integer:=extract(year from coalesce(p_date,current_date)); n integer; begin insert into public.skylight_invoice_counters(tenant_id,invoice_year,last_number) values(p_tenant,y,1) on conflict(tenant_id,invoice_year) do update set last_number=public.skylight_invoice_counters.last_number+1 returning last_number into n; return 'SRM-'||y::text||'-'||lpad(n::text,4,'0'); end$$;
revoke all on function private.next_skylight_invoice_number(uuid,date) from public,anon,authenticated;
create or replace function private.skylight_invoice_before_insert() returns trigger language plpgsql security definer set search_path='' as $$begin if new.invoice_number is null or btrim(new.invoice_number)='' then new.invoice_number:=private.next_skylight_invoice_number(new.tenant_id,new.issue_date); end if; return new; end$$;
revoke all on function private.skylight_invoice_before_insert() from public,anon,authenticated;
drop trigger if exists skylight_invoice_assign_number on public.skylight_invoices; create trigger skylight_invoice_assign_number before insert on public.skylight_invoices for each row execute function private.skylight_invoice_before_insert();
create or replace function private.skylight_invoice_item_total() returns trigger language plpgsql security definer set search_path='' as $$begin new.line_total_cents:=greatest(0,round(new.quantity*new.unit_price_cents)::integer-new.line_discount_cents); new.updated_at:=now(); return new; end$$;
revoke all on function private.skylight_invoice_item_total() from public,anon,authenticated;
drop trigger if exists skylight_invoice_item_total on public.skylight_invoice_items; create trigger skylight_invoice_item_total before insert or update on public.skylight_invoice_items for each row execute function private.skylight_invoice_item_total();
create or replace function private.recalculate_skylight_invoice(p_invoice_id uuid) returns void language plpgsql security definer set search_path='' as $$
declare sub integer:=0; disc integer:=0; rate integer:=0; tax integer:=0; tot integer:=0; paid integer:=0; bal integer:=0; st text; due date; begin select coalesce(sum(line_total_cents),0)::integer into sub from public.skylight_invoice_items where invoice_id=p_invoice_id; select discount_cents,tax_rate_bps,status,due_date into disc,rate,st,due from public.skylight_invoices where id=p_invoice_id; tax:=round(greatest(0,sub-disc)*rate/10000.0)::integer; tot:=greatest(0,sub-disc)+tax; select coalesce(sum(case when kind='payment' then amount_cents else -amount_cents end),0)::integer into paid from public.skylight_invoice_payments where invoice_id=p_invoice_id; bal:=tot-paid; update public.skylight_invoices set subtotal_cents=sub,tax_cents=tax,total_cents=tot,amount_paid_cents=paid,balance_due_cents=bal,status=case when st='void' then 'void' when tot>0 and bal<=0 then 'paid' when paid>0 then 'partial' when due is not null and due<current_date and st in('sent','viewed','overdue') then 'overdue' else st end,paid_at=case when tot>0 and bal<=0 then coalesce(paid_at,now()) when st<>'paid' then null else paid_at end,updated_at=now() where id=p_invoice_id; end$$;
revoke all on function private.recalculate_skylight_invoice(uuid) from public,anon,authenticated;
create or replace function private.skylight_invoice_recalc_from_child() returns trigger language plpgsql security definer set search_path='' as $$begin perform private.recalculate_skylight_invoice(coalesce(new.invoice_id,old.invoice_id)); return coalesce(new,old); end$$;
revoke all on function private.skylight_invoice_recalc_from_child() from public,anon,authenticated;
drop trigger if exists skylight_invoice_items_recalc on public.skylight_invoice_items; create trigger skylight_invoice_items_recalc after insert or update or delete on public.skylight_invoice_items for each row execute function private.skylight_invoice_recalc_from_child();
drop trigger if exists skylight_invoice_payments_recalc on public.skylight_invoice_payments; create trigger skylight_invoice_payments_recalc after insert or update or delete on public.skylight_invoice_payments for each row execute function private.skylight_invoice_recalc_from_child();
create or replace function private.skylight_invoice_recalc_from_invoice() returns trigger language plpgsql security definer set search_path='' as $$begin perform private.recalculate_skylight_invoice(new.id); return new; end$$;
revoke all on function private.skylight_invoice_recalc_from_invoice() from public,anon,authenticated;
drop trigger if exists skylight_invoice_header_recalc on public.skylight_invoices; create trigger skylight_invoice_header_recalc after update of discount_cents,tax_rate_bps on public.skylight_invoices for each row when(old.discount_cents is distinct from new.discount_cents or old.tax_rate_bps is distinct from new.tax_rate_bps) execute function private.skylight_invoice_recalc_from_invoice();

create or replace function public.submit_skylight_service_inquiry(p_tenant_id uuid,p_service_slug text,p_business_name text,p_contact_name text,p_phone text,p_email text,p_message text,p_consent_to_contact boolean) returns uuid language plpgsql security definer set search_path='' as $$declare v_id uuid; begin if coalesce(p_consent_to_contact,false)=false then raise exception 'Contact consent is required.'; end if; if length(btrim(coalesce(p_business_name,'')))<2 then raise exception 'Business name is required.'; end if; if nullif(btrim(coalesce(p_phone,'')),'') is null and nullif(btrim(coalesce(p_email,'')),'') is null then raise exception 'Phone or email is required.'; end if; insert into public.marketing_leads(tenant_id,business_name,contact_name,phone,email,service_interest,message,status,created_at,consent_to_contact,source,landing_path) values(p_tenant_id,left(btrim(p_business_name),160),nullif(left(btrim(coalesce(p_contact_name,'')),120),''),nullif(left(btrim(coalesce(p_phone,'')),80),''),nullif(left(btrim(coalesce(p_email,'')),240),''),nullif(left(btrim(coalesce(p_service_slug,'')),120),''),nullif(left(btrim(coalesce(p_message,'')),2400),''),'new',now(),true,'skylight_services','/skylight-services') returning id into v_id; return v_id; end$$;
revoke all on function public.submit_skylight_service_inquiry(uuid,text,text,text,text,text,text,boolean) from public; grant execute on function public.submit_skylight_service_inquiry(uuid,text,text,text,text,text,text,boolean) to anon,authenticated;
create or replace function public.get_public_skylight_invoice(p_token uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare v_invoice public.skylight_invoices; v_client public.skylight_clients; v_items jsonb; v_payments jsonb; begin select * into v_invoice from public.skylight_invoices where public_token=p_token and status not in('draft','void'); if v_invoice.id is null then return null; end if; select * into v_client from public.skylight_clients where id=v_invoice.client_id; select coalesce(jsonb_agg(jsonb_build_object('description',description,'detail',detail,'quantity',quantity,'unit_price_cents',unit_price_cents,'line_discount_cents',line_discount_cents,'line_total_cents',line_total_cents,'sort_order',sort_order) order by sort_order,id),'[]'::jsonb) into v_items from public.skylight_invoice_items where invoice_id=v_invoice.id; select coalesce(jsonb_agg(jsonb_build_object('kind',kind,'amount_cents',amount_cents,'paid_at',paid_at,'method',method,'reference',reference) order by paid_at,id),'[]'::jsonb) into v_payments from public.skylight_invoice_payments where invoice_id=v_invoice.id; update public.skylight_invoices set viewed_at=coalesce(viewed_at,now()),status=case when status='sent' then 'viewed' else status end,updated_at=now() where id=v_invoice.id; return jsonb_build_object('invoice',jsonb_build_object('invoice_number',v_invoice.invoice_number,'status',case when v_invoice.status='sent' then 'viewed' else v_invoice.status end,'currency',v_invoice.currency,'issue_date',v_invoice.issue_date,'due_date',v_invoice.due_date,'subtotal_cents',v_invoice.subtotal_cents,'discount_cents',v_invoice.discount_cents,'tax_rate_bps',v_invoice.tax_rate_bps,'tax_cents',v_invoice.tax_cents,'total_cents',v_invoice.total_cents,'amount_paid_cents',v_invoice.amount_paid_cents,'balance_due_cents',v_invoice.balance_due_cents,'deposit_required_cents',v_invoice.deposit_required_cents,'terms',v_invoice.terms,'client_note',v_invoice.client_note,'hosted_invoice_url',v_invoice.hosted_invoice_url,'invoice_pdf_url',v_invoice.invoice_pdf_url),'client',jsonb_build_object('company_name',v_client.company_name,'contact_name',v_client.contact_name,'email',v_client.email,'phone',v_client.phone,'billing_address1',v_client.billing_address1,'billing_address2',v_client.billing_address2,'city',v_client.city,'state',v_client.state,'postal_code',v_client.postal_code,'country',v_client.country),'items',v_items,'payments',v_payments); end$$;
revoke all on function public.get_public_skylight_invoice(uuid) from public; grant execute on function public.get_public_skylight_invoice(uuid) to anon,authenticated;

create or replace function private.refresh_skylight_sales_opportunities(p_tenant_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare v_count integer:=0; begin update public.skylight_sales_opportunities set active=false,updated_at=now() where tenant_id=p_tenant_id and stage not in('won','lost'); with candidates as (select p.id prospect_id,p.business_id,p.tenant_id,p.opportunity_score,p.marketing_flags,coalesce(array_agg(distinct m.service_slug order by m.service_slug) filter(where m.service_slug is not null),'{}'::text[]) recommendations,coalesce(sum(distinct m.weight),0)::integer mapped_weight,(select go.id from public.growth_opportunities go where go.tenant_id=p.tenant_id and go.prospect_id=p.id and go.opportunity_type='skylight_marketing' order by go.score desc,go.updated_at desc limit 1) growth_id from public.business_prospects p left join public.skylight_signal_service_map m on m.tenant_id=p.tenant_id and m.active and m.signal_key=any(coalesce(p.marketing_flags,'{}'::text[])) where p.tenant_id=p_tenant_id group by p.id,p.business_id,p.tenant_id,p.opportunity_score,p.marketing_flags having count(m.id)>0), scored as (select *,least(100,greatest(coalesce(opportunity_score,0),35)+least(mapped_weight,45)) score,case when 'web-design'=any(recommendations) then 'web-design' when 'seo'=any(recommendations) then 'seo' when 'google-business-profile-optimization'=any(recommendations) then 'google-business-profile-optimization' when 'lead-generation'=any(recommendations) then 'lead-generation' else recommendations[1] end primary_slug from candidates) insert into public.skylight_sales_opportunities(tenant_id,prospect_id,business_id,growth_opportunity_id,primary_service_slug,recommended_service_slugs,evidence_flags,score,priority,stage,active,updated_at) select tenant_id,prospect_id,business_id,growth_id,primary_slug,recommendations,marketing_flags,score,case when score>=90 then 'hot' when score>=75 then 'high' when score>=55 then 'medium' else 'low' end,'new',true,now() from scored on conflict(tenant_id,prospect_id) do update set business_id=excluded.business_id,growth_opportunity_id=excluded.growth_opportunity_id,primary_service_slug=excluded.primary_service_slug,recommended_service_slugs=excluded.recommended_service_slugs,evidence_flags=excluded.evidence_flags,score=excluded.score,priority=excluded.priority,active=true,updated_at=now(); get diagnostics v_count=row_count; insert into public.skylight_sales_campaign_members(campaign_id,opportunity_id,prospect_id,business_id,status,priority,created_at,updated_at) select c.id,o.id,o.prospect_id,o.business_id,'queued',o.priority,now(),now() from public.skylight_sales_campaigns c join public.skylight_sales_opportunities o on o.tenant_id=c.tenant_id and o.active and c.service_slug=any(o.recommended_service_slugs) where c.tenant_id=p_tenant_id and c.status='active' and c.campaign_type='service_outreach' on conflict(campaign_id,opportunity_id) where opportunity_id is not null do update set priority=excluded.priority,updated_at=now(); return jsonb_build_object('opportunities_refreshed',v_count,'refreshed_at',now()); end$$;
revoke all on function private.refresh_skylight_sales_opportunities(uuid) from public,anon,authenticated;
create or replace function public.refresh_skylight_sales_opportunities(p_tenant_id uuid) returns jsonb language plpgsql security invoker set search_path='' as $$begin if not private.has_tenant_role(p_tenant_id,array['admin','super_admin']) then raise exception 'Admin access is required.'; end if; return private.refresh_skylight_sales_opportunities(p_tenant_id); end$$;
revoke all on function public.refresh_skylight_sales_opportunities(uuid) from public,anon; grant execute on function public.refresh_skylight_sales_opportunities(uuid) to authenticated;
